const float pi = 3.141592;
const float tau = 2.0*pi;



//#define TIME (3.0*tau/4.0)
#define TIME iTime/2.0
vec3 hsv2rgb(vec3 c)
{
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}
const float sphereRadius = 15.0;
const float camRadius = 2.0*sphereRadius;

struct hit {
    bool didHit;
    vec3 col;
};
   bool cube(vec3 p, float sz){
    return abs(p.x)<sz&&abs(p.y)<sz&&abs(p.z)<sz;
}

hit sc(vec3 p,float sz, float iter,float t) 
{     
    if (!cube(p,sz)) {
        return hit(false,vec3(0));
    }
    float len = sz*2.;
    float x = p.x + sz;
    float y = p.y + sz;
    float z = p.z + sz;

    vec3 a=vec3(0,1,1);
    for(float i=0.; i<iter; i++) {
        len /= 3.;         
        if (int(x/len) % 3 == 1 && int(y/len) % 3 == 1 && int(z/len) % 3 == 1) {
            a+=vec3(1./(iter+1.),1,1);  
        }
        if (int(x/len) % 3 == 1 ) {
            a+=vec3(1./(iter+1.),1,1)/2.*sin(t);  
        }
        if (int(y/len) % 3 == 1 ) {
            a+=vec3(1./(iter+1.),1,1)/2.*sin(t);  
        }
        if (int(z/len) % 3 == 1 ) {
            a+=vec3(1./(iter+1.),1,1)/2.*sin(t);  
        }

    }
    return hit(true,hsv2rgb(a));    
}


hit getVoxel(vec3 p) {
hit sc1=sc(p,12.,1.,iTime);
if(!sc1.didHit)return sc1;
return hit(true,abs(sc1.col-sc(p,12.,2.,iTime*1.1).col+-sc(p,12.,3.,iTime*1.2).col-sc(p,12.,4.,iTime*1.3).col+0.1));

}

vec3 lighting(vec3 norm, vec3 pos, vec3 rd, vec3 col) {
    vec3 lightDir = normalize(vec3(-1.0, 3.0, -1.0));
    float diffuseAttn = max(dot(norm, lightDir), 0.0);
    vec3 light = vec3(1.0,0.9,0.9);

    vec3 ambient = vec3(0.2, 0.2, 0.3);

    vec3 reflected = reflect(rd, norm);
    float specularAttn = max(dot(reflected, lightDir), 0.0);

    return col*(diffuseAttn*light*1.0 + specularAttn*light*0.6 + ambient);
}

// Voxel ray casting algorithm from "A Fast Voxel Traversal Algorithm for Ray Tracing" 
// by John Amanatides and Andrew Woo
// http://www.cse.yorku.ca/~amana/research/grid.pdf
hit intersect(vec3 ro, vec3 rd) {
    //Todo: find out why this is so slow
    vec3 pos = floor(ro);

    vec3 step = normalize(rd)/10.;
    vec3 tDelta = step / rd;


    float tMaxX, tMaxY, tMaxZ;
    bool last=false;


    vec3 norm;
    const int maxTrace = 100;
    vec3 col=vec3(0);
    bool dh=false;
    float br=1.;
    float sbr=1.;
    for (int i = 0; i < maxTrace; i++) {
        hit h = getVoxel(pos);
        if (h.didHit) {
            col=(col*(br*0.+1.1)+1.*sin(5.*normalize(pos)))/(br*0.+2.1);

            //col=normalize(col);
            dh=true;
            sbr+=br+1.;
            br+=1.;
            pos+=step/20.;
            i=0;
            step += sin(normalize(h.col))/3000.;


        }
        else pos+=step*5.;

    }

 	return hit(dh,(col));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    vec2 uv = fragCoord / iResolution.xy - 0.5;
    vec3 worldUp = vec3(0,1,0);
    vec3 camPos = vec3(camRadius*sin(TIME*0.1), 10, 1.0*camRadius*cos(TIME*0.1));
    vec3 lookAt = vec3(0,0,0);
    vec3 camDir = normalize(lookAt - camPos);
    vec3 camRight = normalize(cross(camDir, worldUp));
    vec3 camUp = cross(camRight, camDir);

    vec3 filmCentre = camPos + camDir*0.3;
    vec2 filmSize = vec2(1,iResolution.y / iResolution.x);

    vec3 filmPos = filmCentre + uv.x*filmSize.x*camRight + uv.y*filmSize.y*camUp;
    vec3 ro = camPos;
    vec3 rd = normalize(filmPos - camPos);

    hit h = intersect(ro, rd);    
    if(h.didHit) {
        fragColor = vec4(h.col*h.col*2.,1);
    } else{
        fragColor = vec4(0,0,0,0);
    }
}
